'use strict';
let upgradeTooltip=null,upgradePinned=false;
const UPGRADE_STAT_LABELS={hpRegen:'HP REGEN / วินาที',mpRegen:'MP REGEN / วินาที',hp:'HP',mp:'MP',atk:'ATK',atkspd:'ATKSPD',def:'DEF',cri:'CRI',criDamage:'CRI.DAMAGE',acc:'ACC',avoid:'AVOID',spd:'SPD',jump:'JUMP'};
function hideUpgradeTooltip(force=true){if(!force&&upgradePinned)return;if(upgradeTooltip)upgradeTooltip.hidden=true;upgradePinned=false}
function previewFormat(value,suffix=''){return Number(value).toLocaleString('en-US',{maximumFractionDigits:2})+suffix}
function showUpgradeTooltip(anchor,title,rows,note='',pinned=false){if(!upgradeTooltip){upgradeTooltip=document.createElement('div');upgradeTooltip.id='upgradeTooltip';upgradeTooltip.className='upgrade-tooltip';upgradeTooltip.setAttribute('role','tooltip');document.body.append(upgradeTooltip)}upgradePinned=pinned;upgradeTooltip.replaceChildren();const heading=document.createElement('strong');heading.textContent=title;upgradeTooltip.append(heading);for(const [label,current,next,suffix='']of rows){const row=document.createElement('div');row.className='upgrade-compare-row';const name=document.createElement('span');name.textContent=label;const values=document.createElement('span');values.append(document.createTextNode(previewFormat(current,suffix)+' → '));const upgraded=document.createElement('b');upgraded.textContent=previewFormat(next,suffix);if(next>current)upgraded.className='upgrade-gain';values.append(upgraded);row.append(name,values);upgradeTooltip.append(row)}if(note){const small=document.createElement('small');small.textContent=note;upgradeTooltip.append(small)}upgradeTooltip.hidden=false;const r=anchor.getBoundingClientRect(),width=upgradeTooltip.offsetWidth,height=upgradeTooltip.offsetHeight;let x=r.right+10;if(x+width>innerWidth-8)x=r.left-width-10;upgradeTooltip.style.left=Math.max(8,Math.min(innerWidth-width-8,x))+'px';upgradeTooltip.style.top=Math.max(8,Math.min(innerHeight-height-8,r.top))+'px'}
function showStatPreview(key,anchor,pinned=false){if(player[key]>=999){showUpgradeTooltip(anchor,STAT_NAMES[key],[],'ค่าสูงสุดแล้ว',pinned);return}const before=characterStatus(),after=characterStatus({...player,[key]:player[key]+1});const rows=Object.entries(UPGRADE_STAT_LABELS).filter(([id])=>Math.abs(after[id]-before[id])>.001||key==='dex'&&id==='atkspd').map(([id,label])=>[label,before[id],after[id],['cri','criDamage','avoid'].includes(id)?'%':'']);showUpgradeTooltip(anchor,STAT_NAMES[key]+' '+player[key]+' → '+(player[key]+1),rows,'ใช้ 1 AP'+(key==='dex'?' · DEX ทุก 4 แต้ม = 1 ATKSPD':key==='str'?' · STR ทุก 50 แต้ม = 1 HP/วินาที':key==='int'?' · INT ทุก 100 แต้ม = 1 MP/วินาที':''),pinned)}

document.addEventListener('pointerdown',e=>{if(!e.target.closest('.base-stat,.skill-upgrade-wrap,.upgrade-tooltip,.inventory-item,.equipment-slot,.potion-circle'))hideUpgradeTooltip()});
